  1	import http from 'node:http';
  2	import path from 'node:path';
  3	import { readFile, writeFile } from 'node:fs/promises';
  4	import { fileURLToPath } from 'node:url';
  5	
  6	const ROOMS = Object.freeze(['Aurora', 'Borealis', 'Cosmos']);
  7	const MAX_BODY_BYTES = 10000;
  8	const HOST = '127.0.0.1';
  9	const DEFAULT_PORT = 3000;
 10	const DEFAULT_DATA_FILE = 'bookings.json';
 11	const JSON_TYPE = 'application/json; charset=utf-8';
 12	const PUBLIC_DIR = path.join(path.dirname(fileURLToPath(import.meta.url)), 'public');
 13	const STATIC_FILES = Object.freeze({
 14	  '/': { file: 'index.html', type: 'text/html; charset=utf-8' },
 15	  '/app.js': { file: 'app.js', type: 'text/javascript; charset=utf-8' },
 16	});
 17	const BOOKING_KEYS = Object.freeze(['id', 'room', 'title', 'date', 'start', 'end']);
 18	const DATA_KEYS = Object.freeze(['bookings', 'nextId']);
 19	
 20	class HttpError extends Error {
 21	  constructor(status, message) {
 22	    super(message);
 23	    this.status = status;
 24	  }
 25	}
 26	
 27	// ---------- validation ----------
 28	
 29	function isPlainObject(value) {
 30	  return typeof value === 'object' && value !== null && !Array.isArray(value);
 31	}
 32	
 33	function isValidDate(value) {
 34	  if (typeof value !== 'string' || !/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(value)) return false;
 35	  const year = Number(value.slice(0, 4));
 36	  const month = Number(value.slice(5, 7));
 37	  const day = Number(value.slice(8, 10));
 38	  if (year < 2000 || year > 2099 || month < 1 || month > 12 || day < 1) return false;
 39	  const febDays = year % 4 === 0 ? 29 : 28;
 40	  const monthDays = [31, febDays, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
 41	  return day <= monthDays[month - 1];
 42	}
 43	
 44	function isValidTime(value) {
 45	  if (typeof value !== 'string' || !/^[0-9]{2}:[0-9]{2}$/.test(value)) return false;
 46	  return Number(value.slice(0, 2)) <= 23 && Number(value.slice(3, 5)) <= 59;
 47	}
 48	
 49	function isValidTitle(value) {
 50	  return typeof value === 'string' && value.trim().length >= 1 && value.trim().length <= 80;
 51	}
 52	
 53	/** Applies booking rules 4-9 to a parsed body; returns the normalised fields. */
 54	function validateFields(body) {
 55	  if (typeof body.room !== 'string' || !ROOMS.includes(body.room)) {
 56	    throw new HttpError(400, 'room must be one of Aurora, Borealis, Cosmos');
 57	  }
 58	  if (!isValidTitle(body.title)) throw new HttpError(400, 'title must be 1 to 80 characters');
 59	  if (!isValidDate(body.date)) throw new HttpError(400, 'date must be a valid YYYY-MM-DD date');
 60	  if (!isValidTime(body.start)) throw new HttpError(400, 'start must be HH:MM');
 61	  if (!isValidTime(body.end)) throw new HttpError(400, 'end must be HH:MM');
 62	  if (body.end <= body.start) throw new HttpError(400, 'end must be after start');
 63	  return { room: body.room, title: body.title.trim(), date: body.date, start: body.start, end: body.end };
 64	}
 65	
 66	function hasExactKeys(obj, keys) {
 67	  const own = Object.keys(obj).sort();
 68	  return own.length === keys.length && own.every((key, i) => key === keys[i]);
 69	}
 70	
 71	function isStoredBooking(b) {
 72	  return isPlainObject(b) && hasExactKeys(b, [...BOOKING_KEYS].sort())
 73	    && Number.isSafeInteger(b.id) && b.id >= 1
 74	    && ROOMS.includes(b.room) && isValidTitle(b.title) && b.title === b.title.trim()
 75	    && isValidDate(b.date) && isValidTime(b.start) && isValidTime(b.end) && b.end > b.start;
 76	}
 77	
 78	function findOverlaps(bookings, candidate) {
 79	  return bookings.filter((b) => b.room === candidate.room && b.date === candidate.date
 80	    && b.start < candidate.end && candidate.start < b.end);
 81	}
 82	
 83	/** Returns the stored state if `data` is exactly the layout this server writes, else null. */
 84	function parseStoredData(data) {
 85	  if (!isPlainObject(data) || !hasExactKeys(data, DATA_KEYS)) return null;
 86	  const { nextId, bookings } = data;
 87	  if (!Number.isSafeInteger(nextId) || nextId < 1 || !Array.isArray(bookings)) return null;
 88	  const seen = new Set();
 89	  for (const [index, b] of bookings.entries()) {
 90	    if (!isStoredBooking(b) || b.id >= nextId || seen.has(b.id)) return null;
 91	    if (findOverlaps(bookings.slice(0, index), b).length > 0) return null;
 92	    seen.add(b.id);
 93	  }
 94	  return { nextId, bookings: bookings.map((b) => ({ ...b })) };
 95	}
 96	
 97	// ---------- storage ----------
 98	
 99	function createStore(filePath, initial) {
100	  let state = initial;
101	  let queue = Promise.resolve();
102	
103	  async function save(next) {
104	    await writeFile(filePath, JSON.stringify(next));
105	    state = next;
106	  }
107	
108	  /** Runs mutations one at a time so concurrent requests see a consistent state. */
109	  function serialize(task) {
110	    const result = queue.then(() => task(state, save));
111	    queue = result.catch(() => {});
112	    return result;
113	  }
114	
115	  return { get: () => state, serialize };
116	}
117	
118	async function loadState(filePath) {
119	  let text;
120	  try {
121	    text = await readFile(filePath, 'utf8');
122	  } catch (err) {
123	    if (err && err.code === 'ENOENT') return { nextId: 1, bookings: [] };
124	    return null;
125	  }
126	  try {
127	    return parseStoredData(JSON.parse(text));
128	  } catch {
129	    return null;
130	  }
131	}
132	
133	// ---------- HTTP helpers ----------
134	
135	function sendJson(res, status, payload) {
136	  const body = JSON.stringify(payload);
137	  res.writeHead(status, { 'Content-Type': JSON_TYPE, 'Content-Length': Buffer.byteLength(body) });
138	  res.end(body);
139	}
140	
141	function sendError(res, status, message) {
142	  sendJson(res, status, { error: message });
143	}
144	
145	/** Reads the whole body; keeps at most MAX_BODY_BYTES + 1 bytes and counts the rest. */
146	async function readBody(req) {
147	  const chunks = [];
148	  let kept = 0;
149	  let total = 0;
150	  for await (const chunk of req) {
151	    total += chunk.length;
152	    if (kept <= MAX_BODY_BYTES) {
153	      const piece = chunk.subarray(0, MAX_BODY_BYTES + 1 - kept);
154	      chunks.push(piece);
155	      kept += piece.length;
156	    }
157	  }
158	  return { buffer: Buffer.concat(chunks), total };
159	}
160	
161	function isJsonContentType(header) {
162	  if (typeof header !== 'string') return false;
163	  const media = header.split(';')[0].replace(/^[ \t]+|[ \t]+$/g, '');
164	  return media.toLowerCase() === 'application/json';
165	}
166	
167	function compareBookings(a, b) {
168	  if (a.date !== b.date) return a.date < b.date ? -1 : 1;
169	  if (a.start !== b.start) return a.start < b.start ? -1 : 1;
170	  return ROOMS.indexOf(a.room) - ROOMS.indexOf(b.room);
171	}
172	
173	// ---------- handlers ----------
174	
175	function listBookings(store, query, res) {
176	  const params = new URLSearchParams(query);
177	  let bookings = store.get().bookings;
178	  if (params.has('date')) {
179	    const date = params.get('date');
180	    if (!isValidDate(date)) throw new HttpError(400, 'date must be a valid YYYY-MM-DD date');
181	    bookings = bookings.filter((b) => b.date === date);
182	  }
183	  sendJson(res, 200, { bookings: [...bookings].sort(compareBookings) });
184	}
185	
186	function parseBookingBody(req, body) {
187	  if (!isJsonContentType(req.headers['content-type'])) {
188	    throw new HttpError(415, 'content type must be application/json');
189	  }
190	  if (body.total > MAX_BODY_BYTES) throw new HttpError(413, 'body too large');
191	  let parsed;
192	  try {
193	    parsed = JSON.parse(body.buffer.toString('utf8'));
194	  } catch {
195	    parsed = undefined;
196	  }
197	  if (!isPlainObject(parsed)) throw new HttpError(400, 'body must be a JSON object');
198	  return validateFields(parsed);
199	}
200	
201	async function createBooking(store, req, body, res) {
202	  const fields = parseBookingBody(req, body);
203	  const booking = await store.serialize(async (state, save) => {
204	    const overlaps = findOverlaps(state.bookings, fields).sort((a, b) => (a.start < b.start ? -1 : 1));
205	    if (overlaps.length > 0) {
206	      throw new HttpError(409, `room is already booked from ${overlaps[0].start} to ${overlaps[0].end}`);
207	    }
208	    const created = { id: state.nextId, ...fields };
209	    await save({ nextId: state.nextId + 1, bookings: [...state.bookings, created] });
210	    return created;
211	  });
212	  sendJson(res, 201, booking);
213	}
214	
215	async function deleteBooking(store, idText, res) {
216	  if (!/^[1-9][0-9]*$/.test(idText)) throw new HttpError(404, 'booking not found');
217	  await store.serialize(async (state, save) => {
218	    const remaining = state.bookings.filter((b) => String(b.id) !== idText);
219	    if (remaining.length === state.bookings.length) throw new HttpError(404, 'booking not found');
220	    await save({ nextId: state.nextId, bookings: remaining });
221	  });
222	  res.writeHead(204);
223	  res.end();
224	}
225	
226	async function serveStatic(entry, res) {
227	  const content = await readFile(path.join(PUBLIC_DIR, entry.file));
228	  res.writeHead(200, { 'Content-Type': entry.type, 'Content-Length': content.length });
229	  res.end(content);
230	}
231	
232	const BOOKING_PREFIX = '/api/bookings/';
233	
234	/** Dispatches by exact path bytes and method; throws 404/405 when no route matches. */
235	async function route(store, req, res, body) {
236	  const target = req.url;
237	  const q = target.indexOf('?');
238	  const pathname = q === -1 ? target : target.slice(0, q);
239	  const query = q === -1 ? '' : target.slice(q + 1);
240	  const { method } = req;
241	  const expect = (allowed) => {
242	    if (!allowed.includes(method)) throw new HttpError(405, 'method not allowed');
243	  };
244	  if (Object.hasOwn(STATIC_FILES, pathname)) {
245	    expect(['GET']);
246	    return serveStatic(STATIC_FILES[pathname], res);
247	  }
248	  if (pathname === '/api/rooms') {
249	    expect(['GET']);
250	    return sendJson(res, 200, { rooms: [...ROOMS] });
251	  }
252	  if (pathname === '/api/bookings') {
253	    expect(['GET', 'POST']);
254	    return method === 'GET' ? listBookings(store, query, res) : createBooking(store, req, body, res);
255	  }
256	  const rest = pathname.startsWith(BOOKING_PREFIX) ? pathname.slice(BOOKING_PREFIX.length) : '';
257	  if (rest !== '' && !rest.includes('/')) {
258	    expect(['DELETE']);
259	    return deleteBooking(store, rest, res);
260	  }
261	  throw new HttpError(404, 'not found');
262	}
263	
264	function createHandler(store) {
265	  return async (req, res) => {
266	    let body;
267	    try {
268	      body = await readBody(req);
269	    } catch {
270	      res.destroy();
271	      return;
272	    }
273	    try {
274	      await route(store, req, res, body);
275	    } catch (err) {
276	      if (res.headersSent) {
277	        res.destroy();
278	      } else if (err instanceof HttpError) {
279	        sendError(res, err.status, err.message);
280	      } else {
281	        sendError(res, 500, 'internal error');
282	      }
283	    }
284	  };
285	}
286	
287	// ---------- startup ----------
288	
289	function parsePort(raw) {
290	  if (raw === undefined || raw === '') return DEFAULT_PORT;
291	  if (!/^[0-9]+$/.test(raw)) return null;
292	  const port = Number(raw);
293	  return port <= 65535 ? port : null;
294	}
295	
296	function fail(line) {
297	  process.stderr.write(`${line}\n`);
298	  process.exitCode = 1;
299	}
300	
301	async function main() {
302	  const port = parsePort(process.env.PORT);
303	  if (port === null) return fail('invalid PORT');
304	
305	  const dataName = process.env.DATA_FILE || DEFAULT_DATA_FILE;
306	  const dataPath = path.resolve(process.cwd(), dataName);
307	  const initial = await loadState(dataPath);
308	  if (initial === null) return fail(`cannot read data file ${dataName}`);
309	
310	  const store = createStore(dataPath, initial);
311	  const server = http.createServer(createHandler(store));
312	  server.on('error', (err) => {
313	    fail(`cannot listen on port ${port}: ${err && err.code ? err.code : 'error'}`);
314	    process.exit(1);
315	  });
316	  server.listen(port, HOST, () => {
317	    process.stdout.write(`listening on http://${HOST}:${server.address().port}\n`);
318	  });
319	}
320	
321	main().catch(() => {
322	  fail('server failed to start');
323	  process.exit(1);
324	});
